<?php
namespace App\Http\Controllers; use App\Domain\Content\Enums\ContentStatus; use App\Domain\Content\Models\ContentPage; use App\Domain\Content\Models\SiteContent; use App\Domain\Admin\Services\AuditService; use Illuminate\Http\Request; use Inertia\Inertia;
class AdminContentController extends Controller {public function index(){return Inertia::render('Admin/Content/Index',['pages'=>ContentPage::orderBy('title')->get(),'home'=>SiteContent::where('key','homepage')->value('value')??[]]);} public function storePage(Request $r,AuditService $a){$d=$r->validate(['title'=>'required|string|max:160','slug'=>'required|alpha_dash|max:160|unique:content_pages,slug','key'=>'required|alpha_dash|max:100|unique:content_pages,key','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:500']);$p=ContentPage::create($d+['status'=>ContentStatus::Draft,'content'=>[]]);$a->record($r->user(),'content.page_created',$p,$d);return back()->with('success','Content page created.');} public function updatePage(Request $r,ContentPage $page,AuditService $a){$d=$r->validate(['title'=>'required|string|max:160','status'=>'required|in:draft,published','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:500','indexable'=>'required|boolean','content'=>'nullable|array']);$page->update($d+['published_at'=>$d['status']==='published'?($page->published_at?:now()):null]);$a->record($r->user(),'content.page_updated',$page,['status'=>$d['status']]);return back()->with('success','Content page updated.');}}
